              className="shadow-xl"
              as={Link}
              to="/register/student"
            >
              سجل الآن
            </Button>
          </motion.div>
        </div>
      </section>

      {/* Materials Section */}
      <section className="py-20 bg-white dark:bg-[#121212]">
        <div className="container mx-auto px-4">
          <motion.div 
            className="text-center max-w-3xl mx-auto mb-16"
            initial={{ opacity: 0, y: 20 }}
            whileInView={{ opacity: 1, y: 0 }}
            viewport={{ once: true }}
            transition={{ duration: 0.5 }}
