          <div className="grid grid-cols-1 md:grid-cols-3 gap-6 max-w-5xl mx-auto">
            <motion.div 
              className="bg-primary-50 dark:bg-[#1a1a1a] p-6 rounded-2xl shadow-sm"
              initial={{ opacity: 0, y: 20 }}
              whileInView={{ opacity: 1, y: 0 }}
              viewport={{ once: true }}
              transition={{ duration: 0.5 }}
            >
              <h3 className="text-xl font-bold mb-4 text-primary">الصف الأول الثانوي</h3>
              <ul className="space-y-2">
                <li className="bg-white dark:bg-[#2a2a2a] p-3 rounded-lg">الرياضيات</li>
                <li className="bg-white dark:bg-[#2a2a2a] p-3 rounded-lg">الفيزياء</li>
                <li className="bg-white dark:bg-[#2a2a2a] p-3 rounded-lg">الكيمياء</li>
              </ul>
              <div className="mt-4">
                <button className="bg-accent text-white py-2 px-4 rounded-lg w-full">عرض جميع المواد</button>
              </div>
            </motion.div>
            
            <motion.div 
              className="bg-primary-50 dark:bg-[#1a1a1a] p-6 rounded-2xl shadow-sm"
              initial={{ opacity: 0, y: 20 }}
              whileInView={{ opacity: 1, y: 0 }}
              viewport={{ once: true }}
              transition={{ duration: 0.5, delay: 0.1 }}
            >
              <h3 className="text-xl font-bold mb-4 text-primary">الصف الثاني الثانوي</h3>
              <ul className="space-y-2">
                <li className="bg-white dark:bg-[#2a2a2a] p-3 rounded-lg">الرياضيات</li>
                <li className="bg-white dark:bg-[#2a2a2a] p-3 rounded-lg">الفيزياء</li>
                <li className="bg-white dark:bg-[#2a2a2a] p-3 rounded-lg">الكيمياء</li>
              </ul>
              <div className="mt-4">
                <button className="bg-accent text-white py-2 px-4 rounded-lg w-full">عرض جميع المواد</button>
              </div>
            </motion.div>
            
            <motion.div 
              className="bg-primary-50 dark:bg-[#1a1a1a] p-6 rounded-2xl shadow-sm"
              initial={{ opacity: 0, y: 20 }}
              whileInView={{ opacity: 1, y: 0 }}
              viewport={{ once: true }}
              transition={{ duration: 0.5, delay: 0.2 }}
            >
              <h3 className="text-xl font-bold mb-4 text-primary">الصف الثالث الثانوي</h3>
              <ul className="space-y-2">
                <li className="bg-white dark:bg-[#2a2a2a] p-3 rounded-lg">الرياضيات</li>
                <li className="bg-white dark:bg-[#2a2a2a] p-3 rounded-lg">الفيزياء</li>
                <li className="bg-white dark:bg-[#2a2a2a] p-3 rounded-lg">الكيمياء</li>
              </ul>
              <div className="mt-4">
                <button className="bg-accent text-white py-2 px-4 rounded-lg w-full">عرض جميع المواد</button>
              </div>
            </motion.div>
          </div>
        </div>
      </section>
    </PageTransition>
  );
};

export default Home;
